jQuery(window).on("load", function() {
    $('#preloader').fadeOut(500);
    $('#main-wrapper').addClass('show');

    $('body').attr('data-sidebar-style') === "mini" ? $(".hamburger").addClass('is-active') : $(".hamburger").removeClass('is-active')
});

(function($) {
    "use strict";

    $(".manageuser").on("click", function() {
        let elementid = $(this).attr("id");
        let splitter;
        let action;
        let customerType = $("#customertype").val();

        if (elementid.indexOf("disableUser") >= 0) {
            splitter = "disableUser";
            action = "disable";
        } else {
            splitter = "enableUser";
            action = "enable";
        }
        let ukey = elementid.split(splitter)[1];
        let displayresult = $("#actionResult" + ukey);
        $.ajax({
            url: "database/manageuser.php",
            method: "POST",
            data: { action: action, ukey: ukey, custType: customerType },
            cache: false,
            success: function(result) {
                var data = JSON.parse(result);
                console.log(data);
                displayresult.removeClass("hide-element");
                var color;
                if (data.statusCode == 200) {
                    let button = $("#" + elementid);
                    let modalbutton = $("#showmodalaccess" + ukey);
                    if (action == "enable") {
                        button.removeClass("btn-success");
                        button.addClass("btn-danger");
                        $("#actiontitle" + ukey).text("Disable Account");
                        $("#" + elementid + " i").removeClass("fa-user-check");
                        $("#" + elementid + " i").addClass("fa-user-lock");
                        $("#settingTitle" + ukey).text("Disable this account ?");
                        button.attr("id", ("disableUser" + ukey));
                        modalbutton.removeClass("badge-success");
                        modalbutton.addClass("badge-danger");
                        modalbutton.text("Disable");
                        displayresult.text("Account enabled successfully.");
                    } else {
                        button.removeClass("btn-danger");
                        button.addClass("btn-success");
                        $("#actiontitle" + ukey).text('Enable Account');
                        $("#" + elementid + " i").addClass("fa-user-check");
                        $("#" + elementid + " i").removeClass("fa-user-lock");
                        $("#settingTitle" + ukey).text("Enable this account ?");
                        button.attr("id", ("enableUser" + ukey));
                        modalbutton.removeClass("badge-danger");
                        modalbutton.addClass("badge-success");
                        modalbutton.text("Enable");
                        displayresult.text("Account disabled successfully.");
                    }
                    color = "alert-success";
                    displayresult.addClass(color);
                } else if (data.statusCode == 201) {
                    color = "alert-danger";
                    displayresult.addClass(color);
                    displayresult.text("Account update failed.");
                }
                displayresult
                    .delay(3000)
                    .queue(function(next) {
                        displayresult.removeClass(color);
                        displayresult.addClass("hide-element");
                        //$("#editUser" + ukey).modal('hide');

                        next();
                    });

            }
        });
    });

    $(".wholesaleApprovalButton").on("click", function() {
        let elementid = $(this).attr("id");
        let ukey = elementid.split("approveButtonWholesale")[1];
        let result = $("#approvalResult" + ukey);

        $.ajax({
            url: "database/manageuser.php",
            type: "POST",
            data: { action: "approve", ukey: ukey },
            success: function(response) {
                var data = JSON.parse(response);
                if (data.statusCode == 200) {
                    result.removeClass("hide-element");
                    result.addClass("alert-success");
                    result.html("User is now approved and has access to account.");
                    $("#approveButtonWholesale" + ukey).addClass("hide-element");
                    $(".approve-action-for-users").html("<span class='badge badge-pill badge-success'>Verified</span>");

                    //change access
                    let button = $("#enableUser" + ukey);
                    console.log(button);
                    button.removeClass("btn-success");
                    button.addClass("btn-danger");
                    let modalbutton = $("#showmodalaccess" + ukey);
                    $("#actiontitle" + ukey).text('Disable Account');
                    $("#enableUser" + ukey + " i").removeClass("fa-user-check");
                    $("#enableUser" + ukey + " i").addClass("fa-user-lock");
                    $("#settingTitle" + ukey).text("Disable this account ?");
                    button.attr("id", ("disableUser" + ukey));
                    modalbutton.addClass("badge-danger");
                    modalbutton.removeClass("badge-success");
                    modalbutton.text("Disable");

                } else {
                    result.removeClass("hide-element");
                    result.addClass("alert-danger");
                    result.html("Failed to approve user. Please try again.");
                    $(document).delay(5000).queue(function(next) {
                        result.addClass("hide-element");
                        result.removeClass("alert-danger");
                        next();
                    });
                }
            }
        });
    });

    $(".select-brand").on("change", function() {
        let value = $(this).val();
        let id = $(this).attr("id");
        let pID = id.split("val-brand")[1];
        if (value == "new") {
            $("#new-brand" + pID).removeClass("hide-element");
            $("#new-brand" + pID + " input").prop("disabled", false);
        } else {
            $("#new-brand" + pID).addClass("hide-element");
            $("#new-brand" + pID + " input").prop("disabled", true);
        }
    });

    $(".select-category").on("change", function() {
        let value = $(this).val();
        let id = $(this).attr("id");
        let pID = id.split("val-category")[1];
        if (value == "new") {
            $("#val-brand" + pID).text("");
            $("#val-brand" + pID).append("<option value='new'>Choose New Brand</option>");
            $("#new-category" + pID).removeClass("hide-element");
            $("#new-category" + pID + " input").prop("disabled", false);
        } else {
            $.ajax({
                url: "database/getData.php",
                method: "POST",
                data: { "datatype": "CategoryBrand", "category": value },
                cache: false,
                success: function(response) {
                    var data = JSON.parse(response);
                    if (data.code == 200) {
                        $("#val-brand" + pID).text("");
                        $("#val-brand" + pID).append(data.result);
                    }
                }
            });
            $("#new-brand" + pID).removeClass("hide-element");
            $("#new-brand" + pID + " input").prop("disabled", false);
            $("#new-category" + pID).addClass("hide-element");
            $("#new-category" + pID + " input").prop("disabled", true);
        }
    });



    $("#menu").metisMenu();

    $('.nk-nav-scroll').slimscroll({
        position: "right",
        size: "5px",
        height: "100%",
        color: "transparent"
    });



    $(".nav-control").on('click', function() {

        $('#main-wrapper').toggleClass("menu-toggle");

        $(".hamburger").toggleClass("is-active");
    });


    $(function() {
        for (var nk = window.location,
                o = $("ul#menu a").filter(function() {
                    return this.href == nk;
                })
                .addClass("active")
                .parent()
                .addClass("active");;) {
            if (!o.is("li")) break;
            o = o.parent()
                .addClass("in")
                .parent()
                .addClass("active");
        }
    });

    $(function() {
        var win_h = window.outerHeight;
        if (win_h > 0 ? win_h : screen.height) {
            $(".content-body").css("min-height", (win_h + 60) + "px");
        };
    });





    $('.selectpicker').selectpicker();



    $('[data-toggle="popover"]').popover();
    $('[data-toggle="tooltip"]').tooltip();




    const headerHight = $('.header').innerHeight();

    $(window).scroll(function() {
        if ($('body').attr('data-layout') === "horizontal" && $('body').attr('data-header-position') === "static" && $('body').attr('data-sidebar-position') === "fixed")
            $(this.window).scrollTop() >= headerHight ? $('.metismenu').addClass('fixed') : $('.metismenu').removeClass('fixed')
    });

    $('.sidebar-right-trigger').on('click', function() {
        $('.sidebar-right').toggleClass('show');
    });

    $(".orderStatus").on("change", function() {
        let elementid = $(this).attr("id");
        let oid = elementid.split("orderStages")[1];
        let value = $("#orderStages" + oid).val();
        $.ajax({
            url: "database/setordertrack.php",
            type: "POST",
            data: { "action": "setTrack", "orderid": oid, "stage": value },
            cache: false,
            success: function(result) {
                var code = JSON.parse(result);
                if (code.statusCode == 200) {
                    toastr.success('Order delivery stage changed.', 'Status Changed!');
                } else {
                    toastr.error('Failed to update stage.', 'Status Changed!');
                }
            }

        });
    });





})(jQuery);